<body>
  <h1>🐍 贪吃蛇</h1>
  <div class="hud">
    <div>得分 <b id="score">0</b></div>
    <div>最高 <b id="best">0</b></div>
  </div>
  <div class="wrap">
    <canvas id="game" width="400" height="400"></canvas>
    <div class="overlay" id="overlay">
      <h2 id="overlay-title">贪吃蛇</h2>
      <p id="overlay-text">按方向键 / WASD 开始<br>吃到食物变长，别撞墙或撞自己</p>
      <button id="start-btn">开始游戏</button>
